"""Generated by the NL to Flow Diagram Encoder Pipeline."""

num = 23

numCopy = num

byteString = []

bits = 0

while ((2 ** bits) <= num):
    bits = (bits + 1)

if (bits < 7):
    bits = 7

while (bits >= 0):
    value = (2 ** bits)
    if (value > num):
        byteString.append(0)
    else:
        byteString.append(1)
        num = (num - value)
    bits = (bits - 1)

if ((byteString[0] == 0) and (len(byteString) > 8)):
    byteString.pop(0)

bitString = ''

for bit in byteString:
    bitString = (bitString + str(bit))

print(f'{numCopy} = 0b {bitString}')
